package com.benbenyu.btquicklaunch;
import android.content.*;import android.net.Uri;import android.os.Looper;import java.io.*;import java.util.zip.*;
public class DeviceChecks {
 public static void main(String[] args)throws Exception{Looper.prepareMainLooper();Class<?> at=Class.forName("android.app.ActivityThread");Object thread=at.getMethod("systemMain").invoke(null);Context sys=(Context)at.getMethod("getSystemContext").invoke(thread);Context c=sys.createPackageContext("com.benbenyu.btquicklaunch",0);SharedPreferences p=c.getSharedPreferences("stable_qa",0);p.edit().clear().putString("0pkg","mark.via").putString("0name","Backup QA").putBoolean("paper_theme",true).putBoolean("0voice",false).putString("proxy_apps","com.openai.chatgpt,com.google.android.apps.bard").putBoolean("proxy_guard",true).putBoolean("bt_connect_sound",false).putBoolean("reminder_enabled",true).putString("reminder_media","tone").putBoolean("reminder_keyboard_connected",false).putBoolean("reminder_keyboard_disconnected",true).putBoolean("reminder_keyboard_low",true).putBoolean("reminder_phone_low",false).putInt("brightness",25).putInt("background",2).commit();File file=new File("/data/local/tmp/simplehome-qa.zip");ConfigBackup.write(c,p,Uri.fromFile(file));p.edit().clear().commit();ConfigBackup.restore(c,p,Uri.fromFile(file));if(!p.getString("0pkg","").equals("mark.via")||!p.getBoolean("paper_theme",false)||p.getInt("brightness",0)!=25)throw new AssertionError("roundtrip failed");if(!p.getString("proxy_apps","").equals("com.openai.chatgpt,com.google.android.apps.bard")||!p.getBoolean("proxy_guard",false)||p.getBoolean("bt_connect_sound",true))throw new AssertionError("proxy and Bluetooth backup roundtrip failed");if(!p.getString("reminder_media","").equals("tone")||!p.getBoolean("reminder_enabled",false)||p.getBoolean("reminder_keyboard_connected",true)||!p.getBoolean("reminder_keyboard_disconnected",false)||!p.getBoolean("reminder_keyboard_low",false)||p.getBoolean("reminder_phone_low",true))throw new AssertionError("reminder backup roundtrip failed");System.out.println("PASS backup roundtrip with proxy and reminder settings");File bad=new File("/data/local/tmp/simplehome-bad.zip");try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(bad))){zip.putNextEntry(new ZipEntry("config.json"));zip.write("{\"brightness\":\"bad\"}".getBytes("UTF-8"));zip.closeEntry();}boolean rejected=false;try{ConfigBackup.restore(c,p,Uri.fromFile(bad));}catch(Exception expected){rejected=true;}if(!rejected||p.getInt("brightness",0)!=25)throw new AssertionError("invalid backup changed settings");System.out.println("PASS invalid backup rejected without changing settings");byte[] big=new byte[17];boolean limited=false;try{ConfigBackup.read(new ByteArrayInputStream(big),16);}catch(Exception expected){limited=true;}if(!limited)throw new AssertionError("size limit");System.out.println("PASS backup size limit");p.edit().clear().commit();for(java.lang.reflect.Field field:Class.forName("android.bluetooth.IBluetoothHidHost$Stub").getDeclaredFields())if(field.getName().startsWith("TRANSACTION_")){field.setAccessible(true);System.out.println(field.getName()+"="+field.get(null));}System.exit(0);}
}
